program='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    periods = range(2, min(10, max(h, w)) + 1)
    candidates = []
    for period in periods:
        counts = [Counter() for _ in range(period)]
        for r in range(3, h):
            for c in range(3, w):
                value = grid[r][c]
                if value != 0:
                    counts[(r + c) % period][value] += 1
        score = sum(max(bucket.values(), default=0) for bucket in counts)
        candidates.append((score, -period, period, counts))
    _, _, period, counts = max(candidates)
    cycle = [bucket.most_common(1)[0][0] for bucket in counts]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = cycle[(r + c) % period]
    return out
'''
